294		if !pd.Deactivated || pd.DeactivateReason != "stop it" || pd.DeactivatorAccountID != "payer" {
295			t.Fatalf("deactivation info lost: %+v", pd)
296		}
297	
298		wantStates := map[requestKey]RequestState{
299			{accountID: "u1", requestID: "direct"}:          RequestReserved,
300			{accountID: "u1", requestID: "settled"}:         RequestSettled,
301			{accountID: "u1", requestID: "cancel-reserved"}: RequestCancelled,
302			{accountID: "u1", requestID: "pending-due"}:     RequestPendingApproval,
303			{accountID: "u2", requestID: "approved"}:        RequestReserved,
304			{accountID: "u2", requestID: "rejected"}:        RequestRejected,
305			{accountID: "u2", requestID: "cancel-pending"}:  RequestCancelled,
306			{accountID: "u2", requestID: "pending-expired"}: RequestExpired,
307			{accountID: "u1", requestID: "resv-expired"}:    RequestReservationExpired,
308			{accountID: "u1", requestID: "resv-due"}:        RequestReserved,
309			{accountID: "u1", requestID: "no-timeout"}:      RequestReserved,
310			{accountID: "u1", requestID: "same-id"}:         RequestReserved,
311			{accountID: "u2", requestID: "same-id"}:         RequestReserved,
312		}
313		for k, wantState := range wantStates {
314			got, err := w2.Request(k.accountID, k.requestID)
315			if err != nil {
316				t.Fatalf("request %v: %v", k, err)
317			}
318			if got.State != wantState {
319				t.Fatalf("request %v state = %v, want %v", k, got.State, wantState)
320			}
321			want, _ := w.Request(k.accountID, k.requestID)
322			if !requestViewsEqual(got, want) {
323				t.Fatalf("request %v view = %+v, want %+v", k, got, want)
324			}
325		}
326	
327		// 账本严格按原顺序、逐条一致（含未被受理申请的拒绝记录）。
328		wantLedger := w.Ledger()
329		gotLedger := w2.Ledger()
330		if len(gotLedger) != len(wantLedger) {
331			t.Fatalf("ledger len = %d, want %d", len(gotLedger), len(wantLedger))
332		}
333		for i := range wantLedger {
334			if gotLedger[i] != wantLedger[i] {
335				t.Fatalf("ledger[%d] = %+v, want %+v", i, gotLedger[i], wantLedger[i])
336			}
337		}
338	}
