1229	// buildCumulativeQuotaBackup 构造资金完全自洽的备份：账户预留余额、各策略
1230	// 预留/已花费总额均按“现存已预留请求的预估费用”和“已结算请求的实际费用”
1231	// 求和填写，因此余额与各项总额核对必然通过，能否恢复只取决于累计额度判断。
1232	func buildCumulativeQuotaBackup(t *testing.T, t0 time.Time, policies []quotaPolicySpec) []byte {
1233		t.Helper()
1234		b := backupV1{
1235			Version:    backupVersion,
1236			ExportedAt: timeJSON(t0),
1237			Accounts: []accountBackupV1{
1238				{ID: "payer", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1239				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1240				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
1241			},
1242			Sessions: []sessionBackupV1{
1243				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
1244				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
1245			},
1246			Policies: make([]policyBackupV1, 0, len(policies)),
1247			Requests: make([]requestBackupV1, 0),
1248			Ledger:   []ledgerEntryBackupV1{},
1249		}
1250		sessionOf := map[string]string{"u1": "s1", "u2": "s2"}
1251	
1252		var accountReserved int64
1253		for _, ps := range policies {
1254			var reservedTotal, spentTotal int64
1255			b.Policies = append(b.Policies, policyBackupV1{
1256				ID: ps.id, PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
1257				Operation: "charge", Payee: "shop",
1258				StartsAt: timeJSON(t0.Add(-time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
1259				MaxPerRequest:      ps.per,
1260				MaxTotal:           ps.total,
1261				ApprovalThreshold:  ps.threshold,
1262				ApprovalWait:       durationJSON(ps.wait),
1263				MaxReserveDuration: durationJSON(ps.reserveDur),
1264			})
1265			for _, rs := range ps.reqs {
1266				// 待审批系请求统一提交于 t0；发生过预留的“到期”请求（恢复时已到
1267				// 预留截止或已预留超时）提交与预留时刻前移，保证预留时刻不会早于
1268				// 提交时刻。
1269				createdAt := t0
1270				if (rs.state == RequestReserved && rs.due) || rs.state == RequestReservationExpired {
1271					createdAt = t0.Add(-2 * ps.reserveDur)
1272				}
1273				r := requestBackupV1{
1274					PolicyID: ps.id, RequestID: rs.id, AccountID: rs.account, PayerAccountID: "payer",
1275					SessionID: sessionOf[rs.account], Operation: "charge", Payee: "shop",
1276					EstimatedFee: rs.estFee, ActualFee: rs.actualFee,
1277					State:     int(rs.state),
1278					CreatedAt: timeJSON(createdAt),
1279				}
1280				reservedOrigin := rs.state == RequestReserved || rs.state == RequestSettled ||
1281					rs.state == RequestReservationExpired ||
1282					(rs.state == RequestCancelled && rs.wasReserved)
1283				switch rs.state {
1284				case RequestPendingApproval, RequestRejected, RequestExpired:
1285					r.WaitDeadline = timeJSON(t0.Add(ps.wait))
1286				case RequestCancelled:
1287					if !reservedOrigin {
1288						// 待审批取消：等待截止与取消决定时刻必须合法（提交当时取消）。
1289						r.WaitDeadline = timeJSON(t0.Add(ps.wait))
1290						r.DecidedAt = timeJSON(t0)
1291					}
1292				}
1293				if rs.state == RequestRejected {
1294					r.DecidedAt = timeJSON(t0)
1295					r.RejectReason = rs.rejectReason
1296				}
1297				if rs.state == RequestExpired {
1298					r.DecidedAt = timeJSON(t0.Add(ps.wait))
1299				}
1300				if reservedOrigin {
1301					reservedAt := createdAt
1302					r.ReservedAt = timeJSON(reservedAt)
1303					r.ReserveDuration = durationJSON(ps.reserveDur)
1304					if ps.reserveDur > 0 {
1305						r.ReserveDeadline = timeJSON(reservedAt.Add(ps.reserveDur))
1306					}
1307					if ps.threshold > 0 && rs.estFee > ps.threshold {
1308						// 批准路径：批准（预留）时刻不早于提交时刻、严格早于等待
1309						// 截止时刻，等待截止与三者最早值一致。
1310						r.ApproverAccountID = "payer"
1311						r.DecidedAt = timeJSON(reservedAt)
1312						r.WaitDeadline = timeJSON(createdAt.Add(ps.wait))
1313					}
1314				}
1315				if rs.state == RequestSettled {
1316					// 结算必须发生在有效预留期内：启用超时时取预留窗口中点（严格
1317					// 早于截止时刻）；关闭超时时在预留完成时刻结算即合法。
1318					if ps.reserveDur > 0 {
1319						r.SettledAt = timeJSON(time.Time(r.ReservedAt).Add(ps.reserveDur / 2))
1320					} else {
1321						r.SettledAt = r.ReservedAt
1322					}
1323				}
1324				if rs.state == RequestReservationExpired {
1325					r.ReserveExpiredAt = r.ReserveDeadline
1326				}
1327				b.Requests = append(b.Requests, r)
1328	
1329				switch rs.state {
1330				case RequestReserved:
1331					sum, ok := addInt64(reservedTotal, rs.estFee)
1332					if !ok {
1333						t.Fatalf("test setup: reserved sum overflow")
1334					}
1335					reservedTotal = sum
1336					sum, ok = addInt64(accountReserved, rs.estFee)
1337					if !ok {
1338						t.Fatalf("test setup: account reserved overflow")
1339					}
1340					accountReserved = sum
1341				case RequestSettled:
1342					sum, ok := addInt64(spentTotal, rs.actualFee)
1343					if !ok {
1344						t.Fatalf("test setup: spent sum overflow")
1345					}
1346					spentTotal = sum
1347				}
1348			}
1349			for i := range b.Policies {
1350				if b.Policies[i].ID == ps.id {
1351					b.Policies[i].ReservedTotal = reservedTotal
1352					b.Policies[i].SpentTotal = spentTotal
1353				}
1354			}
1355		}
1356		for i := range b.Accounts {
1357			if b.Accounts[i].ID == "payer" {
1358				b.Accounts[i].Reserved = accountReserved
1359			}
1360		}
1361		data, err := json.Marshal(&b)
1362		if err != nil {
1363			t.Fatal(err)
1364		}
1365		return data
1366	}
