3	import (
4		"encoding/json"
5		"errors"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// settleWindowOpts 控制一笔“已结算”请求备份的构造：
12	//   - approved：false 为直接受理路径，true 为超门槛经批准后预留路径；
13	//   - actualFee：结算实际费用（允许为零）；
14	//   - settledAt：备份记载的结算时刻；
15	//   - mutate：在序列化前进一步调整请求/策略/会话字段。
16	//
17	// 除结算时刻由参数指定外，其余计时与金额完全自洽，因此恢复能否成功只取决于
18	// 结算时刻是否落在有效预留期内。两路径均：费用 20、最长预留时长 2h；直接
19	// 受理于 t0，批准路径提交于 t0、于 t0+30m 批准并预留（等待 1h）。
20	type settleWindowOpts struct {
21		approved  bool
22		actualFee int64
23		settledAt time.Time
24		mutate    func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)
25	}
26	
27	func buildSettleWindowBackup(t *testing.T, t0 time.Time, opts settleWindowOpts) []byte {
28		t.Helper()
29		const fee int64 = 20
30		r := requestBackupV1{
31			PolicyID: "p", RequestID: "late", AccountID: "u1", PayerAccountID: "payer",
32			SessionID: "s1", Operation: "charge", Payee: "shop",
33			EstimatedFee: fee,
34			ActualFee:    opts.actualFee,
35			State:        int(RequestSettled),
36			CreatedAt:    timeJSON(t0),
37			SettledAt:    timeJSON(opts.settledAt),
38		}
39		pol := policyBackupV1{
40			ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
41			Operation: "charge", Payee: "shop",
42			StartsAt:           timeJSON(t0.Add(-time.Hour)),
43			EndsAt:             timeJSON(t0.Add(24 * time.Hour)),
44			MaxPerRequest:      100,
45			MaxTotal:           1000,
46			MaxReserveDuration: durationJSON(2 * time.Hour),
47			SpentTotal:         opts.actualFee,
48		}
49		sess := sessionBackupV1{
50			ID: "s1", AccountID: "u1", DeviceID: "d1",
51			ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0.Add(-2 * time.Hour)),
52		}
53		if opts.approved {
54			pol.ApprovalThreshold = 10
55			pol.ApprovalWait = durationJSON(time.Hour)
56			// 提交 t0、等待截止 t0+1h，于 t0+30m 批准并实际预留；预留自批准时刻
57			// 起算，截止 t0+2h30m（等待审批的 30m 不计入）。
58			r.WaitDeadline = timeJSON(t0.Add(time.Hour))
59			r.ReservedAt = timeJSON(t0.Add(30 * time.Minute))
60			r.ReserveDuration = durationJSON(2 * time.Hour)
61			r.ReserveDeadline = timeJSON(t0.Add(2*time.Hour + 30*time.Minute))
62			r.ApproverAccountID = "payer"
63			r.DecidedAt = timeJSON(t0.Add(30 * time.Minute))
64		} else {
65			r.ReservedAt = timeJSON(t0)
66			r.ReserveDuration = durationJSON(2 * time.Hour)
67			r.ReserveDeadline = timeJSON(t0.Add(2 * time.Hour))
68		}
69		if opts.mutate != nil {
70			opts.mutate(&r, &pol, &sess)
71		}
72	
73		// 结算已完成：预留余额为零，可用 = 初始 100 - 实际费用，策略已花费 = 实际费用。
74		b := backupV1{
75			Version:    backupVersion,
76			ExportedAt: timeJSON(t0.Add(-time.Minute)),
77			Accounts: []accountBackupV1{
78				{ID: "payer", Available: 100 - opts.actualFee, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
79				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
80			},
81			Sessions: []sessionBackupV1{sess},
82			Policies: []policyBackupV1{pol},
83			Requests: []requestBackupV1{r},
84			// 既有账本：一条结算扣减记录；恢复后必须原样保留、不追加退款或超时记录。
85			Ledger: []ledgerEntryBackupV1{{
86				Kind: int(LedgerSettle), AccountID: "payer", RequestID: "late",
87				Amount: opts.actualFee, Reason: "settle actual fee", At: timeJSON(opts.settledAt),
88			}},
89		}
90		data, err := json.Marshal(&b)
91		if err != nil {
92			t.Fatal(err)
93		}
94		return data
95	}
96	
97	// assertSettleWindowRejected 恢复必须失败、包装 ErrBackupInvalid，错误信息点名
98	// 使用账户与请求编号并说明结算时刻不在有效预留期内，且不得返回部分钱包。
99	func assertSettleWindowRejected(t *testing.T, data []byte, at time.Time) string {
100		t.Helper()
101		w2, err := restoreAt(data, at)
102		if err == nil {
103			if w2 != nil {
104				t.Fatalf("invalid settled history restored a wallet: %+v", w2)
105			}
106			t.Fatal("invalid settled history restored without error")
107		}
108		if !errors.Is(err, ErrBackupInvalid) {
109			t.Fatalf("err = %v, want ErrBackupInvalid", err)
110		}
111		msg := err.Error()
112		if !strings.Contains(msg, `"u1"`) || !strings.Contains(msg, `"late"`) {
113			t.Fatalf("error %q must name usage account and request id", msg)
114		}
115		if !strings.Contains(msg, "reserve") {
116			t.Fatalf("error %q must explain the settlement is outside the reserve window", msg)
117		}
118		return msg
119	}
120	
121	// TestRestoreSettledWithinReserveWindowAccepted 验证合法结算时刻边界：恰在
122	// 预留完成时刻、截止前一纳秒都可接受；即使很久以后恢复（预留期早结束、申请
123	// 会话已到期/被吊销、策略已结束或被停用），已结算历史原样保留。
124	func TestRestoreSettledWithinReserveWindowAccepted(t *testing.T) {
125		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
126	
127		for _, approved := range []bool{false, true} {
128			pathName := map[bool]string{false: "direct", true: "approved"}[approved]
129			reservedAt := t0
130			deadline := t0.Add(2 * time.Hour)
131			if approved {
132				reservedAt = t0.Add(30 * time.Minute)
133				deadline = t0.Add(2*time.Hour + 30*time.Minute)
134			}
135	
136			t.Run(pathName+" settle exactly at reserved_at restores", func(t *testing.T) {
137				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
138					approved: approved, actualFee: 20, settledAt: reservedAt,
139				})
140				if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
141					t.Fatalf("settle exactly when reservation completes must be legal: %v", err)
142				}
143			})
144	
145			t.Run(pathName+" settle one nanosecond before deadline restores", func(t *testing.T) {
146				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
147					approved: approved, actualFee: 20, settledAt: deadline.Add(-time.Nanosecond),
148				})
149				if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
150					t.Fatalf("settle 1ns before deadline must be legal: %v", err)
151				}
152			})
153	
154			t.Run(pathName+" zero-fee settle within window restores", func(t *testing.T) {
155				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
156					approved: approved, actualFee: 0, settledAt: deadline.Add(-time.Nanosecond),
157				})
158				w2, err := restoreAt(data, t0.Add(48*time.Hour))
159				if err != nil {
160					t.Fatalf("zero-fee in-window settle: %v", err)
161				}
162				r, _ := w2.Request("u1", "late")
163				if r.State != RequestSettled || r.ActualFee != 0 {
164					t.Fatalf("zero-fee settled request = %+v", r)
165				}
166				// 实际费用为零：预留已全额退回，策略已花费总额为零。
167				if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
168					t.Fatalf("balance = %+v, want full refund {100 0}", bal)
169				}
170				if pv, _ := w2.Policy("p"); pv.SpentTotal != 0 {
171					t.Fatalf("spent total = %d, want 0", pv.SpentTotal)
172				}
173			})
174		}
175	}
176	
177	// TestRestoreSettledHistoryPreservedLongAfterRestore 验证很久以后恢复时，期限内
178	// 已完成的结算仍保持已结算：实际费用、结算时间、余额、策略已花费总额与既有
179	// 账本原样保留，不追加退款或超时记录。
180	func TestRestoreSettledHistoryPreservedLongAfterRestore(t *testing.T) {
181		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
182		settledAt := t0.Add(90 * time.Minute) // 直接受理路径截止 t0+2h 之内
183		data := buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 12, settledAt: settledAt})
184	
185		w2, err := restoreAt(data, t0.Add(30*24*time.Hour))
186		if err != nil {
187			t.Fatalf("legal settled history must restore long after deadline: %v", err)
188		}
189		r, _ := w2.Request("u1", "late")
190		if r.State != RequestSettled {
191			t.Fatalf("state = %v, want settled", r.State)
192		}
193		if r.ActualFee != 12 || !r.SettledAt.Equal(settledAt) {
194			t.Fatalf("settled history changed: fee %d at %v", r.ActualFee, r.SettledAt)
195		}
196		if !r.ReserveExpiredAt.IsZero() {
197			t.Fatalf("settled request must not gain a reserve-expired time: %v", r.ReserveExpiredAt)
198		}
199		// 初始 100：实际扣 12，退回差额 8。
200		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 88, Reserved: 0}) {
201			t.Fatalf("balance = %+v, want {88 0}", bal)
202		}
203		if pv, _ := w2.Policy("p"); pv.ReservedTotal != 0 || pv.SpentTotal != 12 {
204			t.Fatalf("policy totals = reserved %d spent %d, want 0/12", pv.ReservedTotal, pv.SpentTotal)
205		}
206		// 既有账本只有原结算记录，未因很久以后恢复而追加退款或超时记录。
207		led := w2.Ledger()
208		if len(led) != 1 || led[0].Kind != LedgerSettle || led[0].Amount != 12 {
209			t.Fatalf("ledger = %+v, want only the original settle entry", led)
210		}
211	}
212	
213	// TestRestoreRejectsSettledAtOrAfterReserveDeadline 验证核心规则：启用预留
214	// 超时时，结算时刻等于或晚于预留截止时刻（含零实际费用）的已结算记录必须
215	// 拒绝；早于实际预留时刻也拒绝。直接受理与批准后预留两条路径一致。
216	func TestRestoreRejectsSettledAtOrAfterReserveDeadline(t *testing.T) {
217		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
218	
219		for _, approved := range []bool{false, true} {
220			pathName := map[bool]string{false: "direct", true: "approved"}[approved]
221			reservedAt := t0
222			deadline := t0.Add(2 * time.Hour)
223			if approved {
224				reservedAt = t0.Add(30 * time.Minute)
225				deadline = t0.Add(2*time.Hour + 30*time.Minute)
226			}
227	
228			cases := []struct {
229				name      string
230				actualFee int64
231				settledAt time.Time
232				reason    string
233			}{
234				{"settle exactly at deadline", 20, deadline, "reserve window"},
235				{"settle one nanosecond after deadline", 20, deadline.Add(time.Nanosecond), "reserve window"},
236				{"settle long after deadline", 20, deadline.Add(24 * time.Hour), "reserve window"},
237				{"zero-fee settle exactly at deadline", 0, deadline, "reserve window"},
238				{"zero-fee settle after deadline", 0, deadline.Add(time.Hour), "reserve window"},
239				{"settle before reserved_at", 20, reservedAt.Add(-time.Nanosecond), "before reserved_at"},
240			}
241			for _, tc := range cases {
242				t.Run(pathName+" "+tc.name, func(t *testing.T) {
243					data := buildSettleWindowBackup(t, t0, settleWindowOpts{
244						approved: approved, actualFee: tc.actualFee, settledAt: tc.settledAt,
245					})
246					// 即使恢复时刻远晚于截止、按超时规则本该全额退回，损坏的已结算
247					// 历史仍必须拒绝，不能当作有效扣费带回钱包。
248					msg := assertSettleWindowRejected(t, data, t0.Add(30*24*time.Hour))
249					if !strings.Contains(msg, tc.reason) {
250						t.Fatalf("error %q must explain %q", msg, tc.reason)
251					}
252				})
253			}
254		}
255	}
256	
257	// TestRestoreSettleWindowUsesApprovalReservedAt 验证审批路径的预留期自批准
258	// 成功、实际冻结费用的时刻起算，等待审批的时间不计入：晚于等待截止、但仍
259	// 早于“批准时刻+预留时长”的结算合法；用提交时间或审批等待期限替代预留期限
260	// 都会错误拒绝/接受。
261	func TestRestoreSettleWindowUsesApprovalReservedAt(t *testing.T) {
262		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
263		// 提交 t0、等待截止 t0+1h、t0+30m 批准预留、预留截止 t0+2h30m。
264	
265		// t0+2h：已过等待截止（t0+1h）、申请会话早已可过期，但仍在预留窗口
266		// [t0+30m, t0+2h30m) 内，必须接受——证明用的是实际预留时刻而非提交/等待期。
267		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
268			approved: true, actualFee: 20, settledAt: t0.Add(2 * time.Hour),
269		})
270		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
271			t.Fatalf("settle after approval-wait deadline but within reserve window must be legal: %v", err)
272		}
273	
274		// 恰在预留截止 t0+2h30m：拒绝（对比若误用提交+2h=t0+2h 会被当成超时，
275		// 上一例已证明不会；本例锁定真正的截止时刻）。
276		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
277			approved: true, actualFee: 20, settledAt: t0.Add(2*time.Hour + 30*time.Minute),
278		})
279		assertSettleWindowRejected(t, data, t0.Add(48*time.Hour))
280	}
281	
282	// TestRestoreSettleWindowSubSecondAndTimezoneInsensitive 验证时间比较依据保存
283	// 的完整时刻：纳秒精度保留，且不同时区表示的同一时刻判断一致。
284	func TestRestoreSettleWindowSubSecondAndTimezoneInsensitive(t *testing.T) {
285		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
286		deadline := t0.Add(2 * time.Hour)
287		loc := time.FixedZone("east", 5*60*60)
288	
289		// 截止前一纳秒，换成 +05:00 时区表示：仍是同一瞬间，必须接受。
290		before := deadline.Add(-time.Nanosecond).In(loc)
291		if before.Equal(deadline) {
292			t.Fatal("test setup: timezone conversion collapsed the instant")
293		}
294		data := buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 20, settledAt: before})
295		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
296			t.Fatalf("same instant in a different timezone must restore: %v", err)
297		}
298	
299		// 截止时刻本身换时区表示：仍是同一瞬间，必须拒绝。
300		atDeadline := deadline.In(loc)
301		data = buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 20, settledAt: atDeadline})
302		assertSettleWindowRejected(t, data, t0.Add(48*time.Hour))
303	}
304	
305	// TestRestoreSettledWithTimeoutDisabledHasNoSettleDeadline 验证关闭预留超时的
306	// 请求沿用原有结算规则：没有截止时刻，很久以后结算仍合法，不人为增加期限。
307	func TestRestoreSettledWithTimeoutDisabledHasNoSettleDeadline(t *testing.T) {
308		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
309		disable := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
310			p.MaxReserveDuration = 0
311		}
312		// 结算时刻远在预留之后，且不携带任何截止时刻：照常恢复。
313		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
314			actualFee: 20, settledAt: t0.Add(24 * time.Hour), mutate: disable,
315		})
316		// builder 默认写了 2h 的预留计时；关闭超时时必须清空，保持备份自洽。
317		var b backupV1
318		if err := json.Unmarshal(data, &b); err != nil {
319			t.Fatal(err)
320		}
321		b.Requests[0].ReserveDuration = durationJSON(0)
322		b.Requests[0].ReserveDeadline = timeJSON(time.Time{})
323		fixed, err := json.Marshal(&b)
324		if err != nil {
325			t.Fatal(err)
326		}
327		w2, err := restoreAt(fixed, t0.Add(30*24*time.Hour))
328		if err != nil {
329			t.Fatalf("settle with reserve timeout disabled must have no deadline: %v", err)
330		}
331		r, _ := w2.Request("u1", "late")
332		if r.State != RequestSettled || !r.ReserveDeadline.IsZero() {
333			t.Fatalf("timeout-disabled settled request = %+v", r)
334		}
335	}
336	
337	// TestRestoreSettledUnaffectedByLaterSessionPolicyLifecycle 验证只要结算在预留
338	// 有效期内合法完成，申请会话后来到期或被吊销、策略结束或被停用，都不应把已
339	// 合法完成的结算变成错误历史。
340	func TestRestoreSettledUnaffectedByLaterSessionPolicyLifecycle(t *testing.T) {
341		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
342		// 直接受理预留 [t0, t0+2h)；在 t0+1h 结算，此时会话、策略均已结束。
343		sessionExpired := func(_ *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
344			s.ExpiresAt = timeJSON(t0.Add(30 * time.Minute))
345		}
346		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
347			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: sessionExpired,
348		})
349		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
350			t.Fatalf("session expiring before a legal settle must not invalidate history: %v", err)
351		}
352	
353		sessionRevoked := func(_ *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
354			s.ExpiresAt = timeJSON(t0.Add(24 * time.Hour))
355			s.Revoked = true
356		}
357		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
358			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: sessionRevoked,
359		})
360		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
361			t.Fatalf("revoked application session must not invalidate a settled reservation: %v", err)
362		}
363	
364		// 策略在结算前已结束，但策略结束不缩短预留：截止 t0+2h 前的结算仍合法。
365		policyEnded := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
366			p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
367		}
368		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
369			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: policyEnded,
370		})
371		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
372			t.Fatalf("policy ending before deadline must not shorten the reserve window: %v", err)
373		}
374	
375		// 策略后来被停用：已合法完成的结算照常恢复。
376		policyDeactivated := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
377			p.Deactivated = true
378			p.DeactivatedAt = timeJSON(t0.Add(90 * time.Minute))
379			p.DeactivatorAccountID = "payer"
380			p.DeactivateReason = "stopped"
381		}
382		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
383			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: policyDeactivated,
384		})
385		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
386			t.Fatalf("later policy deactivation must not invalidate a legal settle: %v", err)
387		}
388	}
389	
390	// TestRestoreRejectsBackupWhenAnySettledRequestOutOfWindow 验证同一备份中只要
391	// 有一笔已结算请求违反预留期限，整个恢复失败、不返回可用钱包，即使另一笔
392	// 已结算请求完全合法。
393	func TestRestoreRejectsBackupWhenAnySettledRequestOutOfWindow(t *testing.T) {
394		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
395		// 两笔零实际费用的已结算请求：late 恰在截止时刻（非法），ok 在窗口内。
396		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
397			actualFee: 0, settledAt: t0.Add(2 * time.Hour), // late：恰在截止 t0+2h
398		})
399		var b backupV1
400		if err := json.Unmarshal(data, &b); err != nil {
401			t.Fatal(err)
402		}
403		b.Requests = append(b.Requests, requestBackupV1{
404			PolicyID: "p", RequestID: "ok", AccountID: "u1", PayerAccountID: "payer",
405			SessionID: "s1", Operation: "charge", Payee: "shop",
406			EstimatedFee: 20, ActualFee: 0, State: int(RequestSettled),
407			CreatedAt: timeJSON(t0), SettledAt: timeJSON(t0.Add(time.Hour)),
408			ReservedAt: timeJSON(t0), ReserveDuration: durationJSON(2 * time.Hour),
409			ReserveDeadline: timeJSON(t0.Add(2 * time.Hour)),
410		})
411		corrupt, err := json.Marshal(&b)
412		if err != nil {
413			t.Fatal(err)
414		}
415		assertSettleWindowRejected(t, corrupt, t0.Add(48*time.Hour))
416	}
417	
418	// TestRestoreLegalExportWithTimeoutSettleRoundTrips 端到端验证当前版本合法导出
419	// 文本继续兼容：在真实钱包中于预留窗口内结算，导出后于很久以后恢复，已结算
420	// 状态、金额与账本完整保留。
421	func TestRestoreLegalExportWithTimeoutSettleRoundTrips(t *testing.T) {
422		w, c := setupTimeout(t, time.Hour)
423		if _, err := w.Apply(timeoutApply()); err != nil { // r1 预留于 t0，截止 t0+1h
424			t.Fatal(err)
425		}
426		c.t = c.t.Add(30 * time.Minute)
427		if _, err := w.Settle("u1", "r1", 7); err != nil { // 窗口内结算
428			t.Fatal(err)
429		}
430		data, err := w.Export()
431		if err != nil {
432			t.Fatal(err)
433		}
434		w2, err := restoreAt(data, c.t.Add(30*24*time.Hour))
435		if err != nil {
436			t.Fatalf("legal in-window settled export must restore long after: %v", err)
437		}
438		r, _ := w2.Request("u1", "r1")
439		if r.State != RequestSettled || r.ActualFee != 7 {
440			t.Fatalf("restored settled request = %+v", r)
441		}
442		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
443			t.Fatalf("ledger entries added on restore: source %d restored %d", l1, l2)
444		}
445		if n := countKind(w2.Ledger(), LedgerReservationExpiration); n != 0 {
446			t.Fatalf("settled request gained timeout entries on restore: %d", n)
447		}
448		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 93, Reserved: 0}) {
449			t.Fatalf("balance = %+v, want {93 0}", bal)
450		}
451	}
